// src/config/wouldyourather.test.js
// The wouldyourather course is regenerated by the pipeline
// (source-to-csv -> translate-master -> configs), so its checked-in content is
// machine-authored and needs the same kind of guard wouldrather.test.js has:
// 70 subtitle tracks once shipped a leading "[N]" batch-index line that the
// player silently skipped, so nothing failed until someone read the raw SRT.
//
// These assertions cover every lesson, not just one, because the translated
// artifacts are exactly where a generator regression shows up.
import { describe, it, expect } from 'vitest';
import wouldyourather from './wouldyourather.json';
import { SimpleVideoStateController } from '../modules/video/simple-video-controller.js';

const LOCALES = ['en', 'es', 'pt', 'bn', 'fr', 'hi'];
const TRANSLATED = ['es', 'pt', 'bn', 'fr', 'hi'];

/** Every step that carries a subtitle track, across every lesson. */
function captionSteps() {
    return wouldyourather.lessons.flatMap((lesson) =>
        (lesson.steps || [])
            .filter((step) => step.subtitles)
            .map((step) => ({
                label: `${lesson.lessonId}/${step.simpleVideoUrl || step.introBackgroundVideoUrl}`,
                lesson,
                step,
            }))
    );
}

function parseCues(srt) {
    const controller = new SimpleVideoStateController({});
    controller.initSubtitles(srt);
    return { isTimed: controller.state.isTimedSubtitles, cues: controller.state.timedSubtitles };
}

/** An SRT document must open on its cue-number line: "1\n00:00:00,000 -->". */
const OPENS_ON_CUE_ONE = /^\s*1\s*\r?\n\s*\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->/;

describe('wouldyourather.json — subtitle tracks', () => {
    const steps = captionSteps();

    it('has caption steps to check', () => {
        expect(steps.length).toBeGreaterThan(0);
    });

    it.each(LOCALES)('every subtitle track carries %s', (locale) => {
        for (const { label, step } of steps) {
            expect(step.subtitles[locale], `${label} missing ${locale}`).toBeTypeOf('string');
            expect(step.subtitles[locale].trim().length, `${label} ${locale} is empty`).toBeGreaterThan(0);
        }
    });

    it.each(LOCALES)('every %s track is a plain phrase for the take it plays', (locale) => {
        // A take speaks ONE phrase, so its subtitle is that phrase with no
        // timings: the player shows it for the video's whole length
        // (SimpleVideoStateController.initSubtitles, no "-->").
        for (const { label, step } of steps) {
            const raw = step.subtitles[locale];
            expect(raw, `${label} ${locale} carries SRT timings`).not.toContain('-->');
            expect(raw.trim(), `${label} ${locale} is blank`).not.toBe('');
            // The track is the step's own phrase in that language.
            const cue = (step.cue || [])[0];
            expect(cue, `${label} has no cue`).toBeDefined();
            expect(raw, `${label} ${locale} does not match its cue`).toBe(cue[locale]);
        }
    });

    it.each(LOCALES)('no %s track carries a stray batch-index marker', (locale) => {
        // The regression this file exists for: a batch-index marker ("[7]")
        // prepended to the document. It would play fine and hide the corruption.
        for (const { label, step } of steps) {
            const raw = step.subtitles[locale];
            expect(/^\s*\[\d+\]/m.test(raw), `${label} ${locale} starts with an index marker`).toBe(false);
        }
    });
});

describe('wouldyourather.json — localized text', () => {
    // A title is a keyword list ("money vs. time, food vs. talk"), and the
    // translator's taught-phrase instruction makes the model hand back
    // "Respuesta: money vs. time, ..." — translated prefix, English body.
    // Comparing strings for equality misses that, so compare vocabulary: the
    // longest run of consecutive words shared with the English source must be
    // short.
    const NOISE = new Set(['ask', 'answer', 'vs', 'or', 'and', 'the', 'a', 'an', 'of', 'in', 'to', 'with']);

    const words = (s) => String(s).toLowerCase()
        .replace(/[^a-z0-9\s]/g, ' ')
        .split(/\s+/)
        .filter((w) => w && !NOISE.has(w));

    /** Longest run of consecutive words shared by both strings. */
    function longestSharedRun(en, translated) {
        const a = words(en), b = new Set(words(translated));
        let best = 0, run = 0;
        for (const w of a) {
            run = b.has(w) ? run + 1 : 0;
            best = Math.max(best, run);
        }
        return best;
    }

    it.each(TRANSLATED)('every %s title is fully translated, not just its prefix', (locale) => {
        for (const lesson of wouldyourather.lessons) {
            const shared = longestSharedRun(lesson.title.en, lesson.title[locale]);
            expect(
                shared,
                `lesson ${lesson.lessonId} ${locale} title shares ${shared} consecutive English words: ${JSON.stringify(lesson.title[locale])}`,
            ).toBeLessThanOrEqual(2);
        }
    });

    it.each(TRANSLATED)('every %s title, mission and cue is actually translated', (locale) => {
        for (const lesson of wouldyourather.lessons) {
            expect(lesson.title[locale], `lesson ${lesson.lessonId} missing ${locale} title`).toBeTypeOf('string');
            expect(lesson.title[locale].trim().length).toBeGreaterThan(0);
            // A translation identical to the English source is an untranslated
            // cell that reached the store (two Spanish titles did once).
            expect(
                lesson.title[locale].trim(),
                `lesson ${lesson.lessonId} ${locale} title is still English`,
            ).not.toBe(lesson.title.en.trim());

            expect(lesson.mission[locale], `lesson ${lesson.lessonId} missing ${locale} mission`).toBeTypeOf('string');
            expect(lesson.mission[locale].trim(), `lesson ${lesson.lessonId} ${locale} mission is still English`)
                .not.toBe(lesson.mission.en.trim());

            for (const step of lesson.steps || []) {
                for (const [i, cue] of (step.cue || []).entries()) {
                    expect(cue[locale], `lesson ${lesson.lessonId} cue ${i} missing ${locale}`).toBeTypeOf('string');
                    expect(cue[locale].trim().length, `lesson ${lesson.lessonId} cue ${i} ${locale} is empty`).toBeGreaterThan(0);
                }
                for (const [i, choice] of (step.chooseStep || []).entries()) {
                    expect(choice.text[locale], `lesson ${lesson.lessonId} choice ${i} missing ${locale}`).toBeTypeOf('string');
                    expect(choice.text[locale].trim().length).toBeGreaterThan(0);
                }
            }
        }
    });
});

describe('wouldyourather.json — lesson titles are generic', () => {
    // The profile labels a friend's lesson by POSITION ("Lesson N of 6"), so
    // the titles no longer advertise topics — a topic list in a title is
    // exactly what went stale before (the Oct-14 rewrite left five lessons
    // naming retired topics). The title is the course topic plus the lesson's
    // own letter, and nothing else.
    const TOPIC = {
        en: 'Preferences',
        es: 'Preferencias',
        pt: 'Preferências',
        bn: 'পছন্দ',
        fr: 'Préférences',
        hi: 'पसंद',
    };

    it.each(wouldyourather.lessons.map((l) => l.lessonId))(
        'lesson %s is titled "<topic> <letter>" in every locale',
        (lessonId) => {
            const lesson = wouldyourather.lessons.find((l) => l.lessonId === lessonId);
            for (const locale of LOCALES) {
                expect(
                    lesson.title[locale],
                    `lesson ${lessonId} ${locale} title`,
                ).toBe(`${TOPIC[locale]} ${lessonId.toUpperCase()}`);
            }
        }
    );

    it('no title names a topic any more', () => {
        for (const lesson of wouldyourather.lessons) {
            const words = lesson.title.en.split(/\s+/).slice(1);
            expect(words, `lesson ${lesson.lessonId} title carries a topic list`).toEqual([lesson.lessonId.toUpperCase()]);
        }
    });
});

describe('wouldyourather.json — French and Hindi lesson coverage', () => {
    // The reported regression: a French guest saw the UI in French but the
    // mission and every cue/subtitle in English, because no fr translation
    // existed (Spanish worked — es was present). Hindi had the same gap.
    // Every lesson's mission, cue element and subtitle track must carry fr
    // and hi.
    it.each(wouldyourather.lessons.map((l) => l.lessonId))('lesson %s mission carries fr and hi', (lessonId) => {
        const lesson = wouldyourather.lessons.find((l) => l.lessonId === lessonId);
        for (const lang of ['fr', 'hi']) {
            expect(typeof lesson.mission?.[lang], `lesson ${lessonId} mission.${lang}`).toBe('string');
            expect(lesson.mission[lang].trim().length, `lesson ${lessonId} mission.${lang} empty`).toBeGreaterThan(0);
        }
    });

    it('every cue element carries non-empty fr and hi translations', () => {
        for (const lesson of wouldyourather.lessons) {
            for (const step of lesson.steps || []) {
                for (const cue of step.cue || []) {
                    for (const lang of ['fr', 'hi']) {
                        expect(typeof cue[lang], `${lesson.lessonId}/${step.simpleVideoUrl} cue.${lang}`).toBe('string');
                        expect(cue[lang].trim().length, `${lesson.lessonId} cue.${lang} empty`).toBeGreaterThan(0);
                    }
                }
            }
        }
    });

    it('every branching choice carries non-empty fr and hi translations', () => {
        let choices = 0;
        for (const lesson of wouldyourather.lessons) {
            for (const step of lesson.steps || []) {
                for (const choice of step.chooseStep || []) {
                    choices++;
                    for (const lang of ['fr', 'hi']) {
                        expect(typeof choice.text?.[lang], `${lesson.lessonId} chooseStep.${lang}`).toBe('string');
                        expect(choice.text[lang].trim().length, `${lesson.lessonId} chooseStep.${lang} empty`).toBeGreaterThan(0);
                    }
                }
            }
        }
        expect(choices).toBeGreaterThan(0);
    });
});
